const r = await tools.exec_command({
  cmd:"python - <<'PY'
import pandas as pd,glob,re
b=pd.read_csv('production_batches.csv'); a=pd.read_csv('machine_assignment_log.csv'); q=pd.read_csv('quality_inspections.csv'); p=pd.read_csv('products.csv')
x=b.merge(a[['job_id','start_time']],on='job_id').merge(q,on=['batch_id','product_id']).merge(p[['product_id','quality_rejection_threshold_pct']],on='product_id')
x['prod_ts']=pd.to_datetime('2025-01-01')+pd.to_timedelta(x.production_day-1,unit='D')+pd.to_timedelta(x.start_time+':00');x['excess']=x.rejected_pct-x.quality_rejection_threshold_pct
rows=[]
for path in glob.glob('raw_service_reports/**/*.txt',recursive=True):
 d={}
 for line in open(path):
  if ': ' in line:
   k,v=line.strip().split(': ',1);d[k]=v
 rows.append(d)
m=pd.DataFrame(rows);m['maint_ts']=pd.to_datetime('2025-01-01')+pd.to_timedelta(m.DAY.astype(int)-1,unit='D')+pd.to_timedelta(m.COMPLETED+':00')
x=pd.merge_asof(x.sort_values('prod_ts'),m[['maint_ts','MACHINE','WORK ORDER','TECHNICIAN']].sort_values('maint_ts'),left_on='prod_ts',right_on='maint_ts',left_by='machine_id',right_by='MACHINE',direction='backward')
r=x[(x.inspection_result=='REJECTED')&(x.excess>.02)].copy()
print('high-excess rejects',len(r))
for keys,g in r.groupby(['TECHNICIAN','WORK ORDER','machine_id'],dropna=False):
 print('\n',keys,'count',len(g))
 print(g[['production_day','batch_id','product_id','rejected_pct','excess']].sort_values(['production_day','batch_id']).to_string(index=False))
PY",
  workdir:"/app",yield_time_ms:10000,max_output_tokens:30000
});
text(r.output);

