const r = await tools.exec_command({
  cmd:"python - <<'PY'
import pandas as pd, glob, numpy as np
# data
b=pd.read_csv('production_batches.csv');a=pd.read_csv('machine_assignment_log.csv');q=pd.read_csv('quality_inspections.csv');p=pd.read_csv('products.csv')
x=b.merge(a[['job_id','start_time']],on='job_id').merge(q,on=['batch_id','product_id']).merge(p[['product_id','quality_rejection_threshold_pct']],on='product_id')
x['ts']=pd.Timestamp('2025-01-01')+pd.to_timedelta(x.production_day-1,unit='D')+pd.to_timedelta(x.start_time+':00')
rows=[]
for path in glob.glob('raw_service_reports/**/*.txt',recursive=True):
 d=dict(line.strip().split(': ',1) for line in open(path) if ': ' in line); rows.append(d)
m=pd.DataFrame(rows);m['ts']=pd.Timestamp('2025-01-01')+pd.to_timedelta(m.DAY.astype(int)-1,unit='D')+pd.to_timedelta(m.COMPLETED+':00');m=m.sort_values(['MACHINE','ts']);m['mseq']=m.groupby('MACHINE').cumcount()
x=pd.merge_asof(x.sort_values('ts'),m[['ts','MACHINE','WORK ORDER','TECHNICIAN','mseq']].sort_values('ts'),on='ts',left_by='machine_id',right_by='MACHINE',direction='backward')
cands=['TECH_002','TECH_003','TECH_014','TECH_021','TECH_027','TECH_030','TECH_031','TECH_037']
an=x[(x.TECHNICIAN.isin(cands))&(x.inspection_result.eq('REJECTED'))&(x.rejected_pct>=.075)][['TECHNICIAN','WORK ORDER','machine_id','mseq','product_id']].drop_duplicates()
# stats helper
for _,row in an.sort_values(['TECHNICIAN','WORK ORDER','product_id']).iterrows():
 vals=[]
 for delta,label in [(-1,'prev'),(0,'curr'),(1,'next')]:
  g=x[(x.machine_id==row.machine_id)&(x.mseq==row.mseq+delta)&(x.product_id==row.product_id)]
  if len(g): vals.append(f"{label}:n={len(g)},rej={(g.inspection_result=='REJECTED').sum()},pct={g.rejected_pct.min():.3f}-{g.rejected_pct.max():.3f},mean={g.rejected_pct.mean():.3f}")
  else: vals.append(f'{label}:n=0')
 print(row.TECHNICIAN,row['WORK ORDER'],row.machine_id,row.product_id,' | '.join(vals))
PY",
  workdir:"/app",yield_time_ms:10000,max_output_tokens:25000
});
text(r.output);

